contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: first pay an arbitrary amount 'a', then pay exactly TICKET_AMOUNT (10) as 't'.
    // Finally assert that the pot observed before the second play equals the ticket amount.
    function run(uint a, uint t) public payable {
        // require caller funds for any payments we will forward
        require(address(this).balance >= a + t, "insufficient balance for test");
        // first call: send arbitrary payment a to c.play()
        c.play{value: a}();
        // read pot after first call
        uint potAfterFirst = c.pot();
        // second call: send payment t to c.play()
        c.play{value: t}();
        // read pot after second call
        uint potAfterSecond = c.pot();

        // We require that the second payment equals the contract's TICKET_AMOUNT constant value used by original contract.
        // The original contract requires msg.value == 10, so we constrain t to be 10 here.
        require(t == 10, "second payment must be ticket amount 10");

        // General distinguishing assertion:
        // In the original contract: before the second play the pot must equal the ticket amount (10)
        // because the first call would have reverted unless a == 10. In the mutant, the first call can change pot to a,
        // making potBeforeSecond possibly != 10. We express this by comparing potAfterFirst to the expected ticket amount.
        assert(potAfterFirst == 10);
    }

    // Allow funding this contract for send-forward tests
    receive() external payable {}
}

