pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary payment amount sent to play()
    // General rule to test: after any single call to play() (with any msg.value), the reference contract's pot is always a multiple of C.TICKET_AMOUNT.
    // The mutant that removes the require can accept arbitrary msg.value and thus can make pot not be a multiple of TICKET_AMOUNT for some inputs.
    function testFuzz_property(uint256 pay) public {
        // keep domain wide but avoid trivially impossible transfers (e.g., zero-value is allowed)
        // bound to a reasonable max so vm.deal isn't excessive but still wide enough to find mismatches
        uint256 amount = bound(pay, 0, 1_000_000);

        // fund the caller
        address player = address(0xBEEF);
        vm.deal(player, amount + 1 ether);
        vm.prank(player);
        // perform the payable call; we ignore whether it reverted or not — the property concerns pot state when call completes
        // using try/catch to ensure the call doesn't revert the test; if it reverts, we consider that the call didn't complete and skip
        bool ok;
        try c.play{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Observe the contract only through its public getter: pot()
        // The intended universal property: whenever the play call completed (ok == true), pot is a multiple of TICKET_AMOUNT
        // This is true for the reference implementation for all inputs, but the mutant (which allows arbitrary msg.value) can produce pot not divisible by TICKET_AMOUNT for some pay.
        if (ok) {
            uint256 pot = c.pot();
            // single assertion that must hold for reference and be violated by mutant for some fuzzed input
            assertTrue(pot % c.TICKET_AMOUNT() == 0);
        } else {
            // If call reverted, still assert true on a trivially true property about pot (to keep single assertion path when ok==false)
            // We assert the pot is a multiple of TICKET_AMOUNT even if call reverted — reference still satisfies this.
            uint256 pot = c.pot();
            assertTrue(pot % c.TICKET_AMOUNT() == 0);
        }
    }
}

