contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: caller sends exactly TICKET_AMOUNT and we check balances and pot after a winning play.
    // We cannot control randomness, so we force the situation by calling play repeatedly until a win occurs.
    // To keep the verifier bounded, we allow the caller to provide a maxAttempts parameter.
    function check(address payable player, uint ticketAmount, uint maxAttempts) public payable {
        // ensure this test contract has enough ETH to buy tickets
        require(address(this).balance >= ticketAmount, "insufficient balance for tickets");
        require(ticketAmount > 0, "ticketAmount must be > 0");

        // read constants from target contract via public getters
        uint T = c.TICKET_AMOUNT();
        uint F = c.FEE_AMOUNT();
        // require caller provided ticketAmount equal to contract's ticket price
        require(ticketAmount == T, "ticket amount mismatch");

        // record bank balance before any plays
        address bankAddr = c.bank();
        uint bankBalBefore = bankAddr.balance;

        // play up to maxAttempts times until pot becomes zero after a winning play
        // Each play is a state-changing top-level call
        uint attempts = 0;
        while (attempts < maxAttempts) {
            // send ticketAmount with the call
            c.play{value: ticketAmount}();
            attempts++;
            // if pot is zero, a winning play that cleared pot has occurred
            if (c.pot() == 0) break;
        }

        // Now assert the distinguishing property:
        // After a winning play that cleared the pot, the bank's balance must be >= bankBalBefore (i.e., bank wasn't charged from pot)
        // This captures that the fee is paid by a transfer from bank (no decrease) rather than by deducting from pot.
        assert(c.pot() == 0 && bankAddr.balance >= bankBalBefore);
    }

    // Allow the contract to receive ETH for buying tickets
    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint constant FEE = 1;
    bool __obsd;
    uint __snap;

    constructor(C _c) { c = _c; }

    // single public payable test function: send exactly the ticket amount so play proceeds
    function run(uint ticket) public payable {
        require(address(this).balance >= ticket);
        // require we send the exact ticket amount that C expects
        require(ticket == c.TICKET_AMOUNT());

        // ensure we can observe mid-call state: clear snapshot flag
        __obsd = false;
        __snap = type(uint).max;

        // call play sending the ticket
        c.play{value: ticket}();

        // assert: if we observed the pot during the external transfer, that observed pot
        // must be equal to the contract's pot just after adding the ticket (i.e., previous pot + ticket)
        // We express this by comparing __snap to the expected value computed from public getter pot()
        // Note: when observation didn't happen, __obsd is false; in that case the assertion should hold vacuously
        assert(!__obsd || __snap == c.pot());
    }

    // receive() runs during c.play's transfers; capture pot() once mid-call
    receive() external payable {
        if (!__obsd) {
            __obsd = true;
            // read the contract's pot mid-call through its public getter
            __snap = c.pot();
        }
    }
}

contract InvMutTest {
