pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: seed to influence block.timestamp/block.difficulty via vm.warp and vm.roll,
    // and an address actor who will call play().
    function testFuzz_property(uint256 timeDelta, uint256 blockDelta, address actor) public {
        // keep inputs wide but sensible
        timeDelta = bound(timeDelta, 0, 1 days);
        blockDelta = bound(blockDelta, 0, 1000);
        vm.assume(actor != address(0));

        // Arrange: fund actor so they can pay the ticket
        uint256 ticket = 10; // matches contract's constant TICKET_AMOUNT
        vm.deal(actor, ticket);

        // Advance chain state according to fuzzed params to influence pseudo-random outcome
        vm.warp(block.timestamp + timeDelta);
        vm.roll(block.number + blockDelta);

        // Act: actor calls play() sending exactly ticket
        vm.prank(actor);
        bool ok;
