        // but we can reproduce the same randomness computation here and check that whenever
        // that randomness modulo 2 equals 0, the contract's pot getter is 0 after the call.
        // Recompute the pseudo-random value using the same public inputs (block.timestamp, block.difficulty).
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty)));

        // If (random % 2 == 0) then the reference contract MUST have pot == 0 after play
        if (random % 2 == 0) {
            // Observe contract only via its public getter 'pot'
            assertTrue(c.pot() == 0);
        } else {
            // If random%2 != 0 we make no assertion (admissible behavior varies)
            assertTrue(true);
        }
    }
}

