pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and a seed used to try to influence block.timestamp/block.difficulty via vm.warp
    function testFuzz_property(address caller, uint256 warpTime) public {
        // admissible fuzz domain: caller must not be zero address and must be a distinct EOA we can fund
        vm.assume(caller != address(0));

        // give the caller enough ETH to buy a ticket
        vm.deal(caller, 1 ether);

        // Warp time to help the fuzzer explore random outcomes (though not strictly necessary)
        // keep warpTime within a wide range
        uint256 t = bound(warpTime, 1, type(uint256).max - 1);
        vm.warp(t);

        // Make the call as the fuzzed caller, paying exactly the ticket amount (10 wei in contract)
        uint256 ticket = 10; // matches C.TICKET_AMOUNT
        vm.prank(caller);
        // call play and ignore revert (play has require on msg.value so ensure correct)
        try c.play{value: ticket}() {
            // call succeeded
        } catch {
            // if it reverted, nothing else to assert about pot change for this input
        }

        // The universal property: after any completed play call (whether it resulted in win or not),
        // the reference contract guarantees that if a win occurred and payout executed, pot is reset to 0.
        // We assert that pot is either 0 or equals the ticket (if caller didn't win and pot just increased by ticket).
        // Concretely: pot must be either 0 or exactly ticket * k where k is a nonzero integer; here after one play
        // admissible pots are 0 (if win occurred and pot reset) or 10 (if no win occurred). We assert that pot <= 10.
        // This single assertion distinguishes the reference (which sets pot to 0 on wins) from the mutant
        // that can leave pot > 10 after a winning payout because it didn't reset pot.

        // read pot via public getter
        uint256 pot = c.pot();

        // EXACTLY one assertion: require that pot is <= ticket (i.e., either 0 or 10) which holds for reference
        // but is violated by the mutant when a win pays out and pot is not reset (pot would still include prior pot+ticket)
        assertTrue(pot <= ticket);
    }
}
